head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.strCBData;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 영문공시제출 오픈시 아래 부분 삭제
        //--------------------------------------------------
        label_28.hide();
        pnl_eng_fil.hide();
        //----------------------------------------------------

        $c.libRoundPanel.PanelToGroupBox(panel_1);
        scwin.hideDebugCtrls();
        scwin.strCBData = "^선택하세요,04^공시발간자료,02^자료실,31^공시체크포인트,32^업무사례,62^밸류업자료실(국문)";
        cmb_MENU_FLAG.CBData = scwin.strCBData;
        cmb_MENU_FLAG.setValue('');
        scwin.setCode();
        await scwin.initPage();
        scwin.setKclicStatus('init');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30403.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_AddRow_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_AddRow_onclick = async function() {
    try {
        // 공시발간자료 일 경우에만 파일첨부 6개까지 허용 가능토록 수정 by LDJ_20130219
        if (cmb_MENU_FLAG.getValue() === "04") {
            if (dts_FILE_LIST.getRowCount() === 6) {
                await $c.win.alert("더이상 추가하실 수 없습니다.");
                return;
            }
        } else {
            if (dts_FILE_LIST.getRowCount() === 5) {
                await $c.win.alert("더이상 추가하실 수 없습니다.");
                return;
            }
        }
        btn_File.open();

        // 파일 확장자 체크 추가
        const vFile = btn_File.getValue();
        let vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm !== "") {
            if (await scwin.checkMaxLength1(vFileNm, '80', "파일명")) return; // 파일명 80자 체크
            if (await scwin.checkExtension(vFileNm)) return; // 파일 확장자 체크
            dts_FILE_LIST.insertRow();
        } else {
            return;
        }
        if (!scwin.canUploadFile(btn_File.FileInfo('size'))) {
            await $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
            dts_FILE_LIST.removeRow(dts_FILE_LIST.getRowPosition());
            return;
        } else {
            if (btn_File.getValue() !== "") {
                dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "ATTACH_FILE_NM", btn_File.getValue());
                dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "FILEURL", btn_File.getValue());
            } else {
                dts_FILE_LIST.removeRow(dts_FILE_LIST.getRowPosition());
            }
        }
        btn_File.setValue("");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30403.btn_AddRow_onclick" });
    }
};

/**
 * @method
 * @name btn_DelRow_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_DelRow_onclick = function() {
    try {
        dts_FILE_LIST.removeRow(dts_FILE_LIST.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.btn_DelRow_onclick" });
    }
};

/**
