 */
scwin.trs_Save_OnFail = async function() {
    try {
        await scwin.showAlertMsg(trs_Save.ErrorMsg); // 20250718
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30403.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        const fr_fn_Search = $c.frame.path("../").fn_listDsclBbs;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30403.trs_Save_OnSuccess" });
    }
};

/**
