/**
 * @method
 * @name cmb_MENU_FLAG_onselchange
 * @description cmb_MENU_FLAG onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_MENU_FLAG_onselchange = async function() {
    try {
        const gValueUp = $c.cp.valueOfIndex(cmb_MENU_FLAG, "VALUE", cmb_MENU_FLAG.getSelectedIndex());
        if (gValueUp === '62') {
            // 밸류업자료실(국문)
            rdo_mkt_gubun.setValue('9');
            rdo_mkt_gubun.setDisabled(true);
            if (chk_OBJ_SYSTEM2.getValue() === "Y" &&
                chk_OBJ_SYSTEM1.getValue() === "N" &&
                chk_OBJ_SYSTEM3.getValue() === "N" &&
                chk_OBJ_SYSTEM4.getValue() === "N" &&
                chk_OBJ_SYSTEM5.getValue() === "N") {

            } else {
                await $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. \n공지대상시스템을 [조회(국문)]만 선택해주세요.");
            }
        } else if (gValueUp === '63') {
            // 밸류업자료실(영문)
            if (chk_OBJ_SYSTEM2.getValue() === "N" &&
                chk_OBJ_SYSTEM1.getValue() === "N" &&
                chk_OBJ_SYSTEM3.getValue() === "N" &&
                chk_OBJ_SYSTEM4.getValue() === "N" &&
                chk_OBJ_SYSTEM5.getValue() === "Y") {

            } else {
                await $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. \n공지대상시스템을 [조회(영문)]만 선택해주세요.");
            }
        } else {
            rdo_mkt_gubun.setDisabled(false);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30403.cmb_MENU_FLAG_onselchange" });
    }
};

/**
 * @method
 * @name chk_OBJ_SYSTEM4_onclick
 * @description chk_OBJ_SYSTEM4 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_OBJ_SYSTEM4_onclick = function() {
    try {
        // K-CLIC
        scwin.setKclicStatus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.chk_OBJ_SYSTEM4_onclick" });
    }
};

/**
 * @method
 * @name chk_OBJ_SYSTEM1_onclick
 * @description chk_OBJ_SYSTEM1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_OBJ_SYSTEM1_onclick = function() {
    try {
        // 제출(국문)
        if (chk_OBJ_SYSTEM1.checked === true) {
            cmb_MENU_FLAG.setDisabled(false);
            if (chk_OBJ_SYSTEM4.checked === false) {
                cmb_sprt_room_grp.setDisabled(true);
                cmb_chrg_inst_id.setDisabled(true);
                cmb_sprt_room_grp.setValue('');
                cmb_chrg_inst_id.setValue('');
            }
        }
        if (chk_OBJ_SYSTEM5.checked === false && chk_OBJ_SYSTEM4.checked === false && chk_OBJ_SYSTEM2.checked === false && chk_OBJ_SYSTEM1.checked === false) {
            cmb_sprt_room_grp.setDisabled(false);
            cmb_chrg_inst_id.setDisabled(false);
            cmb_MENU_FLAG.setDisabled(false);
            rdo_mkt_gubun.setDisabled(false);
        }
        scwin.setKclicStatus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.chk_OBJ_SYSTEM1_onclick" });
    }
};

/**
 * @method
 * @name chk_OBJ_SYSTEM2_onclick
 * @description chk_OBJ_SYSTEM2 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_OBJ_SYSTEM2_onclick = function() {
    try {
        // 조회(국문)
        if (chk_OBJ_SYSTEM2.checked === true) {
            cmb_MENU_FLAG.setDisabled(false);
            if (chk_OBJ_SYSTEM4.checked === false) {
                cmb_sprt_room_grp.setDisabled(true);
                cmb_chrg_inst_id.setDisabled(true);
                cmb_sprt_room_grp.setValue('');
                cmb_chrg_inst_id.setValue('');
            }
        }
        if (chk_OBJ_SYSTEM5.checked === false && chk_OBJ_SYSTEM4.checked === false && chk_OBJ_SYSTEM2.checked === false && chk_OBJ_SYSTEM1.checked === false) {
            cmb_sprt_room_grp.setDisabled(false);
            cmb_chrg_inst_id.setDisabled(false);
            cmb_MENU_FLAG.setDisabled(false);
            rdo_mkt_gubun.setDisabled(false);
        }
        scwin.setKclicStatus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30403.chk_OBJ_SYSTEM2_onclick" });
    }
};

/**
 * @method
 * @name chk_OBJ_SYSTEM5_onclick
 * @description chk_OBJ_SYSTEM5 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_OBJ_SYSTEM5_onclick = async function() {
    try {
        // 조회(영문)
        if (chk_OBJ_SYSTEM5.checked === true) {
            scwin.strCBData = "^선택하세요,04^공시발간자료,02^자료실,31^공시체크포인트,32^업무사례,62^밸류업자료실(국문),63^밸류업자료실(영문)";
            cmb_MENU_FLAG.CBData = scwin.strCBData;
            cmb_MENU_FLAG.setValue('63');
            cmb_MENU_FLAG.setDisabled(true);
            rdo_mkt_gubun.setValue('9');
            rdo_mkt_gubun.setDisabled(true);
            cmb_sprt_room_grp.setDisabled(true);
            cmb_chrg_inst_id.setDisabled(true);
            cmb_sprt_room_grp.setValue('');
            cmb_chrg_inst_id.setValue('');
            if (chk_OBJ_SYSTEM4.checked === true || chk_OBJ_SYSTEM3.checked === true ||
                chk_OBJ_SYSTEM2.checked === true || chk_OBJ_SYSTEM1.checked === true) {
                await $c.win.alert("조회(영문) 시스템은 다른 시스템과 같이 사용할 수 없습니다.");
            }
            chk_OBJ_SYSTEM4.setValue(0);
            chk_OBJ_SYSTEM4.setDisabled(true);
            chk_OBJ_SYSTEM3.setValue(0);
            chk_OBJ_SYSTEM3.setDisabled(true);
            chk_OBJ_SYSTEM2.setValue(0);
            chk_OBJ_SYSTEM2.setDisabled(true);
            chk_OBJ_SYSTEM1.setValue(0);
            chk_OBJ_SYSTEM1.setDisabled(true);
        } else {
            scwin.strCBData = "^선택하세요,04^공시발간자료,02^자료실,31^공시체크포인트,32^업무사례,62^밸류업자료실(국문)";
            cmb_MENU_FLAG.CBData = scwin.strCBData;
            cmb_MENU_FLAG.setValue('');
            cmb_MENU_FLAG.setDisabled(false);
        }
        if (chk_OBJ_SYSTEM5.checked === false && chk_OBJ_SYSTEM4.checked === false && chk_OBJ_SYSTEM2.checked === false && chk_OBJ_SYSTEM1.checked === false) {
            cmb_sprt_room_grp.setDisabled(false);
            cmb_chrg_inst_id.setDisabled(false);
            cmb_MENU_FLAG.setDisabled(false);
            rdo_mkt_gubun.setDisabled(false);
            chk_OBJ_SYSTEM4.setDisabled(false);
            chk_OBJ_SYSTEM3.setDisabled(false);
            chk_OBJ_SYSTEM2.setDisabled(false);
            chk_OBJ_SYSTEM1.setDisabled(false);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30403.chk_OBJ_SYSTEM5_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
