        target : "dts_FILE_LIST=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    if (frame.FrameID === "INTEBBS_NEW") {
        // gfm은 정적인 화면이라 변수값을 받을 수 없어. 창의 이름으로 신규와 수정을 구별한다.
        await scwin.setNewMode();
        txb_WRTR_EMP_NO.setValue(scwin.gEmpNo);
        txb_WRTR_EMP_NM.setValue(js_emp_nm);
        txb_LD_MKT_TP_CD.setValue(scwin.gLdMktTp);
        cmb_MENU_FLAG.setSelectedIndex(0);
        chk_OBJ_SYSTEM1.setValue("N");
        chk_OBJ_SYSTEM2.setValue("N");
        chk_OBJ_SYSTEM3.setValue("N");
        chk_OBJ_SYSTEM4.setValue("N");
        chk_OBJ_SYSTEM5.setValue("N");
        btn_Delete.hide();
    } else {
        await scwin.setEditMode();
    }
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {

};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_WRTR_EMP_NM.getValue() === "") {
        await $c.win.alert("[등록자]를 입력하세요.");
        return false;
    }
    if (txb_WRTR_EMP_NM.getValue().length > 10) {
        await $c.win.alert("[등록자]명을 10자 이내로 입력해 주세요.");
        txb_WRTR_EMP_NM.focus();
        return false;
    }
    if (chk_OBJ_SYSTEM1.getValue() === "N" &&
        chk_OBJ_SYSTEM2.getValue() === "N" &&
        chk_OBJ_SYSTEM3.getValue() === "N" &&
        chk_OBJ_SYSTEM4.getValue() === "N" &&
        chk_OBJ_SYSTEM5.getValue() === "N") {
        await $c.win.alert("[공지대상시스템]를 선택하세요.");
        return false;
    }
    if (txb_WRTR_EMAIL.getValue() === "") {
        await $c.win.alert("[이메일]를 입력하세요.");
        txb_WRTR_EMAIL.focus();
        return false;
    }
    if ($c.stf.IsValidEmail(txb_WRTR_EMAIL.getValue()) === false) {
        await $c.win.alert("[이메일] 정확하지 않습니다.");
        txb_WRTR_EMAIL.focus();
        return false;
    }
    if (txb_PW.getValue() === "") {
        await $c.win.alert("[비밀번호]를 입력하세요.");
        txb_PW.focus();
        return false;
    }
    if (txb_TITLE.getValue() === "") {
        await $c.win.alert("[제목]를 입력하세요.");
        txb_TITLE.focus();
        return false;
    }
    if (cmb_MENU_FLAG.getValue() === "" && chk_OBJ_SYSTEM4.checked !== true) {
        await $c.win.alert("[메뉴구분]를 선택하세요.");
        cmb_MENU_FLAG.focus();
        return false;
    }
    if (rdo_mkt_gubun.getValue() === "") {
        await $c.win.alert("[시장구분]를 선택하세요.");
        rdo_mkt_gubun.focus();
        return false;
    }
    if (txa_CONTN_CONTN.getValue() === "") {
        await $c.win.alert("[내용]를 입력하세요.");
        txa_CONTN_CONTN.focus();
        return false;
    }
    if (txb_CONTN_ID.getValue() === "") {
        // alert("[비밀번호]를 입력하세요.");txb_CONTN_ID.focus();return false;

    }
    if (txb_WRTR_EMP_NO.getValue() === "") {
        // alert("[비밀번호]를 입력하세요.");txb_WRTR_EMP_NO.focus();return false;

    }
    if (cmb_MENU_FLAG.getValue() === "31" || cmb_MENU_FLAG.getValue() === "32") {
        if (cmb_MENU_FLAG.getValue() === "31" && (chk_OBJ_SYSTEM1.getValue() === "N" || (chk_OBJ_SYSTEM1.getValue() === "Y" && chk_OBJ_SYSTEM2.getValue() === "Y"))) {
            await $c.win.alert("[공시체크포인트]는 제출시스템에만 적용됩니다.\n공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if (cmb_MENU_FLAG.getValue() === "32" && (chk_OBJ_SYSTEM1.getValue() === "N" || (chk_OBJ_SYSTEM1.getValue() === "Y" && chk_OBJ_SYSTEM2.getValue() === "Y"))) {
            await $c.win.alert("[업무사례]는 제출시스템에만 적용됩니다.\n공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if (cmb_MENU_FLAG.getValue() === "31" && rdo_mkt_gubun.getValue() === "4") {
            await $c.win.alert("[공시체크포인트]은 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
        if (cmb_MENU_FLAG.getValue() === "32" && rdo_mkt_gubun.getValue() === "4") {
            await $c.win.alert("[업무사례]는 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
        // alert("[비밀번호]를 입력하세요.");txb_WRTR_EMP_NO.focus();return false;

    }
    // 202405 밸류업 추가
    if (cmb_MENU_FLAG.getValue() === "62") {
        if (chk_OBJ_SYSTEM2.getValue() === "Y" &&
            chk_OBJ_SYSTEM1.getValue() === "N" &&
            chk_OBJ_SYSTEM3.getValue() === "N" &&
            chk_OBJ_SYSTEM4.getValue() === "N" &&
            chk_OBJ_SYSTEM5.getValue() === "N") {

        } else {
            await $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. \n공지대상시스템을 [조회(국문)]만 선택하여주세요.");
            return false;
        }
    }
    if (cmb_MENU_FLAG.getValue() === "63") {
        if (chk_OBJ_SYSTEM2.getValue() === "N" &&
            chk_OBJ_SYSTEM1.getValue() === "N" &&
            chk_OBJ_SYSTEM3.getValue() === "N" &&
            chk_OBJ_SYSTEM4.getValue() === "N" &&
            chk_OBJ_SYSTEM5.getValue() === "Y") {

        } else {
            await $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. \n공지대상시스템을 [조회(영문)]만 선택하여주세요.");
            return false;
        }
    }
    if (chk_OBJ_SYSTEM4.getValue() === "Y") {
        // K-CLIC
        if (cmb_sprt_room_grp.getValue() === "") {
            await $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 게시물유형을 선택해 주세요.");
            cmb_sprt_room_grp.focus();
            return false;
        }
        if (cmb_chrg_inst_id.getValue() === "") {
            await $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 담당기관을 선택해 주세요.");
            cmb_chrg_inst_id.focus();
            return false;
        }
        /*
        if(getObjectValue(cmb_MENU_FLAG) != "02"){
        	alert("공지대상시스템이 K-CLIC인 경우에는 메뉴구분은 자료실만 선택가능합니다.");
        	cmb_MENU_FLAG.Focus();
        	return false;
        }*/
    }

    // 날짜확인
    if (!$c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        edt_SDate.focus();
        return false;
    }
    return true;
};

/**
         * @method
         * @name save
         * @description save 처리
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.save = async function() {
    if (await scwin.checkForm() === false) return;
    //    alert(dts_MASTER.namestring(1, "OBJ_SYSTEM1"));
    //    alert(dts_MASTER.namestring(1, "OBJ_SYSTEM2"));
    //    return;
    let res = window.confirm("[저장]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "저장";
        let url = "/IntegratedBBS.do?method=registerDsclBbs" + "&SCREN_ID=" + "ULDSTF30403.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        // alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER, I:pFile=dts_FILE_LIST)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    const vPW = txb_PW.getValue();
    if (vPW === "") {
        await $c.win.alert("[비밀번호]를 입력하세요.");
        txb_PW.focus();
        return;
    }
    let res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "삭제";
        let url = "/IntegratedBBS.do?method=removeDsclBbs" + "&SCREN_ID=" + "ULDSTF30403.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        // alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name downLoad
 * @description down Load 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.downLoad = function(row, colid) {
    const filename = dts_FILE_LIST.getCellData(row, "ATTACH_FILE_NM");
    if (filename === "") return;
    if (colid === "ATTACH_FILE_NM") {
        let vCONTN_ID = dts_FILE_LIST.getCellData(row, "CONTN_ID");
        const vCONTN_ATTACH_SEQ = dts_FILE_LIST.getCellData(row, "CONTN_ATTACH_SEQ");
        location.href = "/filedownload.do?file_id=" + vCONTN_ID + "&attach_seq=" + vCONTN_ATTACH_SEQ + "&gubun=2";
    }
};

/**
 * @method
 * @name setKclicStatus
 * @description set Kclic Status 처리
 * @param {*} status status
 * @returns {void}
 * @hidden N
 */
scwin.setKclicStatus = function(status) {
    if (chk_OBJ_SYSTEM4.checked === true) {
        cmb_sprt_room_grp.setDisabled(false);
        cmb_chrg_inst_id.setDisabled(false);
        if (chk_OBJ_SYSTEM2.checked === false && chk_OBJ_SYSTEM1.checked === false) {
            if ('init' !== status) {
                cmb_MENU_FLAG.setValue('02');
            }
            cmb_MENU_FLAG.setDisabled(true);
        }
    } else if (chk_OBJ_SYSTEM5.checked === true) {
        scwin.strCBData = "^선택하세요,04^공시발간자료,02^자료실,31^공시체크포인트,32^업무사례,62^밸류업자료실(국문),63^밸류업자료실(영문)";
        cmb_MENU_FLAG.CBData = scwin.strCBData;
        cmb_MENU_FLAG.setValue('63');
        cmb_MENU_FLAG.setDisabled(true);
        rdo_mkt_gubun.setValue('9');
        rdo_mkt_gubun.setDisabled(true);
        cmb_sprt_room_grp.setDisabled(true);
        cmb_chrg_inst_id.setDisabled(true);
        cmb_sprt_room_grp.setValue('');
        cmb_chrg_inst_id.setValue('');
        chk_OBJ_SYSTEM4.setValue(0);
        chk_OBJ_SYSTEM4.setDisabled(true);
        chk_OBJ_SYSTEM3.setValue(0);
        chk_OBJ_SYSTEM3.setDisabled(true);
        chk_OBJ_SYSTEM2.setValue(0);
        chk_OBJ_SYSTEM2.setDisabled(true);
        chk_OBJ_SYSTEM1.setValue(0);
        chk_OBJ_SYSTEM1.setDisabled(true);
    } else {
        cmb_sprt_room_grp.setDisabled(true);
        cmb_chrg_inst_id.setDisabled(true);
        cmb_sprt_room_grp.setValue('');
        cmb_chrg_inst_id.setValue('');
        cmb_MENU_FLAG.setDisabled(false);
    }
    if (chk_OBJ_SYSTEM5.checked === false && chk_OBJ_SYSTEM4.checked === false && chk_OBJ_SYSTEM2.checked === false && chk_OBJ_SYSTEM1.checked === false) {
        cmb_sprt_room_grp.setDisabled(false);
        cmb_chrg_inst_id.setDisabled(false);
        cmb_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
    }
};

/**
 * @method
 * @name canUploadFile
 * @description 2017-02-13 KBoY FileSizeLimit 30MB
 * @param {Number} size size
 * @returns {void}
 * @hidden N
 */
scwin.canUploadFile = function(size) {
    const maxFileSize = 1024 * 1024 * 30; // 30MB
    if (size < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name checkExtension
 * @description 20250718 파일 확장자 체크로직 추가
 * @param {String} fileNm fileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkExtension = async function(fileNm) {
    const fileExts = new Array(".hwp", ".docx", ".doc", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf", ".gif", ".jpg", ".jpeg", ".bmp", ".tif", ".txt", ".drt", ".dsd", ".png", ".zip"); // 허가 확장자 목록
    const vsFileNm = fileNm;
    const vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    let vsFlag = true;
    const ext = fileNm.substr(fileNm.lastIndexOf(".")).toLowerCase();
    for (let i = 0; i < fileExts.length; i++) {
        if (fileExts[i] === vsFileExts || fileExts[i] === ext) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        await $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};

/**
 * @method
 * @name showAlertMsg
 * @description 20250718
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showAlertMsg = async function(msg) {
    if (msg.indexOf('50014') !== -1) {
        await $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else {
        await $c.win.alert(msg);
    }
};

/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {*} filestr filestr
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(filestr, size, lbl) {
    const overLen = ($c.stf.getStringSize(filestr) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 의 최대길이는 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return true;
    }
    return false;
};
